extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	clear_printed()
	var scene := await instantiate_scene("res://rock.tscn")
	if not check("rock_loaded", scene != null, "La scena rock.tscn deve aprirsi senza errori"):
		return
	var rock := scene as Sprite2D
	if not check("rock_type", rock != null, "La radice della scena rock.tscn deve essere uno Sprite2D"):
		return
	check("pos", rock.position == Vector2(200, 80), "La roccia deve trovarsi a Vector2(200, 80)")
	check("modulate", rock.modulate == Color.RED, "La roccia deve essere colorata con Color.RED")
	check("output", "Roccia pronta:" in printed_text(), "Lo script deve stampare un testo contenente 'Roccia pronta:'")
